"use client"

import * as React from "react"
import { highlight } from "sugar-high"

import { cn } from "@/lib/utils"
import { roll } from "@/lib/0db/roll"
import { Button } from "@/components/ui/button"

type SourceProps = Omit<React.ComponentProps<"figure">, "children"> & {
  code: string
  /** The file's name. Wide, it stands in the margin the way a score names its instrument. */
  title?: React.ReactNode
  /** Hide the Copy action. */
  noCopy?: boolean
}

/**
 * Indentation you can see: a proportional face makes two spaces nearly nothing, so each line's
 * leading spaces become --i (a tab counts two) and the line is indented by that many half-ems.
 * Turnovers hang beneath it, like verse.
 */
function indent(html: string, code: string) {
  const lead = code.split("\n").map((l) => l.match(/^[ \t]*/)![0])
  return html
    .split("\n")
    .map((line, n) => {
      const space = lead[n] ?? ""
      let drop = space.length
      const depth = space.length + (space.match(/\t/g)?.length ?? 0)
      let out = ""
      let i = 0
      while (i < line.length && drop > 0) {
        if (line[i] === "<") {
          const end = line.indexOf(">", i) + 1
          out += line.slice(i, end)
          i = end
        } else if (line[i] === " " || line[i] === "\t") {
          drop--
          i++
        } else break
      }
      return (out + line.slice(i)).replace(/^<span class="sh__line">/, `<span class="sh__line" style="--i:${depth}">`)
    })
    .join("") // the lines are blocks: a newline between them would open a blank line
}

/**
 * Code, set as type. Weight is the only highlighting: the language's words are ink at 500, signs recede
 * to pencil, and what someone wrote (strings, JSX text, comments) is the expression italic.
 * A bracket joins the lines like a system in a score; copying runs the accent down it once.
 */
function Source({ code, title, noCopy = false, className, ...props }: SourceProps) {
  const text = code.replace(/\n$/, "")
  const html = React.useMemo(() => indent(highlight(text), text), [text])
  const [copied, setCopied] = React.useState(0)
  return (
    <figure data-slot="source" data-copied={copied || undefined} className={cn("db-source", className)} {...props}>
      <div className="db-source-frame">
        {title || !noCopy ? (
          <figcaption data-slot="source-meta" className="db-source-meta">
            {title ? <span className="db-source-name">{typeof title === "string" ? named(title) : title}</span> : null}
            {noCopy ? null : <CopyButton text={code} onCopied={() => setCopied((c) => c + 1)} />}
          </figcaption>
        ) : null}
        {/* Keyed by the copy count, so each copy replays the run down the bracket. */}
        <pre key={copied} className="db-source-code" tabIndex={0} data-lines={text.split("\n").length}>
          <code dangerouslySetInnerHTML={{ __html: html }} />
        </pre>
      </div>
    </figure>
  )
}

/** A file name with its extension set back in pencil; a long path may break after a slash. */
function named(title: string) {
  const dot = title.lastIndexOf(".")
  const cut = dot > 0 && dot > title.lastIndexOf("/") ? dot : title.length
  return (
    <>
      {title
        .slice(0, cut)
        .split(/(?<=\/)/)
        .map((part, i) => (
          <React.Fragment key={i}>
            {i ? <wbr /> : null}
            {part}
          </React.Fragment>
        ))}
      {cut < title.length ? <span className="db-source-ext">{title.slice(cut)}</span> : null}
    </>
  )
}

type CopyButtonProps = React.ComponentProps<typeof Button> & {
  text: string
  /** Called once the text is on the clipboard. */
  onCopied?: () => void
}

/** Copy keeps its name through the flow: Copy, then Copied. */
function CopyButton({ text, onCopied, variant = "quiet", className, ...props }: CopyButtonProps) {
  const label = React.useRef<HTMLSpanElement>(null)
  const [copied, setCopied] = React.useState(false)
  const timer = React.useRef<ReturnType<typeof setTimeout>>(undefined)

  React.useEffect(() => () => clearTimeout(timer.current), [])

  const show = (next: boolean) => {
    if (label.current) roll(label.current, () => setCopied(next), "0.5em", next ? 1 : -1)
    else setCopied(next)
  }

  return (
    <Button
      variant={variant}
      data-slot="source-copy"
      className={cn("db-source-copy", className)}
      onClick={async () => {
        try {
          await navigator.clipboard.writeText(text)
        } catch {
          return // the browser refused; the label stays "Copy", which is true
        }
        onCopied?.()
        show(true)
        clearTimeout(timer.current)
        timer.current = setTimeout(() => show(false), 1800)
      }}
      {...props}
    >
      <span ref={label} aria-live="polite">
        {copied ? "Copied" : "Copy"}
      </span>
    </Button>
  )
}

export { Source, CopyButton, type SourceProps, type CopyButtonProps }

@layer components {
  /* ── db-source ── code, set as type. Weight is the only highlighting: the language's words
     are ink at 500, signs recede to pencil, and what someone wrote (strings, JSX text, comments)
     is the expression italic. A bracket joins the lines like a system in a score, the line
     numbers stand before it like bar numbers, and wide, the file's name stands in the margin
     the way a score names its instrument. Copying runs the accent down the bracket once. */
  .db-source { --db-source-gutter: 2.75rem; --db-source-lh: 1.625rem; container-type: inline-size; margin: 0; min-width: 0; }
  .db-source-frame { display: grid; grid-template-columns: minmax(0, 1fr); row-gap: var(--db-space-3); }

  .db-source-meta {
    display: flex; flex-wrap: wrap; align-items: baseline; column-gap: var(--db-space-4); row-gap: var(--db-space-1);
    padding-inline-start: var(--db-source-gutter);
    font-size: var(--db-pp); line-height: var(--db-pp-lh); letter-spacing: var(--db-pp-tr); color: var(--db-graphite);
  }
  .db-source-name { min-width: 0; overflow-wrap: anywhere; }
  .db-source-ext { color: var(--db-pencil); }
  .db-source-copy { margin-inline-start: auto; }
  .db-source-meta > .db-source-copy { font-size: inherit; }
  .db-source-copy > span { display: inline-block; }

  /* Wide enough for a margin: the name and Copy stand to the left of the lines. */
  @container (min-width: 34rem) {
    .db-source-frame:has(> .db-source-meta) { grid-template-columns: 8.5rem minmax(0, 1fr); column-gap: var(--db-space-3); }
    .db-source-meta { flex-direction: column; align-items: flex-start; row-gap: var(--db-space-2); padding-inline-start: 0; padding-block-start: 0.4em; }
    .db-source-copy { margin-inline-start: 0; }
  }

  .db-source-code {
    position: relative; margin: 0; padding-block: 0.25rem; padding-inline-start: var(--db-source-gutter);
    counter-reset: db-line; white-space: pre-wrap; overflow-wrap: anywhere;
    font-family: var(--db-voice); font-stretch: 88%; font-size: 0.9375rem; line-height: var(--db-source-lh); letter-spacing: 0.005em;
    font-variant-numeric: tabular-nums lining-nums; color: var(--db-graphite);
    --sh-keyword: var(--db-ink); --sh-entity: var(--db-ink); --sh-class: var(--db-ink);
    --sh-identifier: var(--db-graphite); --sh-property: var(--db-graphite);
    --sh-string: var(--db-ink); --sh-jsxliterals: var(--db-ink);
    --sh-sign: var(--db-pencil); --sh-comment: var(--db-pencil); --sh-space: inherit;
  }
  .db-source-code:focus-visible { outline-offset: 6px; }
  .db-source-code > code { display: block; font: inherit; }

  /* Each line hangs: indented by its depth, its turnovers a step further in. */
  .db-source-code .sh__line {
    position: relative; display: block; min-block-size: var(--db-source-lh);
    padding-inline-start: calc(var(--i, 0) * 0.5em + 1.5em); text-indent: -1.5em;
  }
  .db-source-code .sh__line::before {
    counter-increment: db-line; content: counter(db-line) / "";
    position: absolute; inset-block-start: 0.1em; inset-inline-start: calc(-1 * var(--db-source-gutter)); width: calc(var(--db-source-gutter) - 1.35rem);
    text-align: end; text-indent: 0; font-size: 0.75em; font-stretch: 100%; color: var(--db-pencil); opacity: 0.6;
    transition: opacity var(--db-allegro), color var(--db-allegro);
  }
  .db-source-code .sh__line:hover::before { opacity: 1; color: var(--db-ink); }
  .db-source-code[data-lines="1"] .sh__line::before { content: none; }

  .db-source-code .sh__token--keyword { font-weight: 500; }
  .db-source-code :is(.sh__token--string, .sh__token--jsxliterals, .sh__token--comment) {
    font-family: var(--db-expression); font-style: italic; font-stretch: 100%; letter-spacing: 0;
    font-size: calc(var(--db-expression-scale) * 1em); line-height: 1;
  }

  /* The bracket: a hairline joining the lines, hooked at both ends. Copying runs the accent down it. */
  .db-source-code::before, .db-source-code::after {
    content: ""; position: absolute; inset-block: 0.55rem; inset-inline-start: calc(var(--db-source-gutter) - 0.9rem); width: 0.3rem;
    border: var(--db-hairline) solid var(--db-rule-strong); border-inline-end: 0; pointer-events: none;
  }
  .db-source-code::after { border-color: var(--db-accent); border-inline-start-width: var(--db-stroke); opacity: 0; }
  .db-source[data-copied] .db-source-code::after { animation: db-source-run var(--db-adagio) var(--db-breath) both; }
  @keyframes db-source-run {
    0%   { opacity: 1; clip-path: inset(0 0 100% 0); }
    55%  { opacity: 1; clip-path: inset(0 0 0 0); }
    100% { opacity: 0; clip-path: inset(0 0 0 0); }
  }
}
